// 28 voices from the Electronic & Music Maker / Music Technology DX7 type-in series,
// stored as packed 128-byte VMEM records. Descriptions and programming notes:
// https://bobbyblues.recup.ch/yamaha_dx7/patches/EMM.html
//
// Each entry gives the instrument family used for matching, then descriptive tags
// drawn from the original programmers' notes.

import { unpackVoice } from "./dx7.js";

const BANK =
  "";

const META = [
  ["bass", "funk bass punchy plucked deep sequenced synth"],
  ["bell", "string bell chime hollow evolving wash hybrid pad"],
  ["brass", "grand brass ensemble powerful bright stab"],
  ["epiano", "wurlitzer electric piano tine touch sensitive dynamic warm"],
  ["keys", "split keyboard dual layered bass piano"],
  ["bass", "funk twang thump clavinet plucked bass metallic silky"],
  ["lead", "full synth muted strident penetrating brassy expressive poly"],
  ["lead", "lead full organ brass portamento sustained buzzy"],
  ["piano", "honky tonk old piano broken acoustic detuned"],
  ["brass", "brass solo trumpet expressive wheel aftertouch"],
  ["bass", "funk bass punchy sequenced bright vibrato"],
  ["bass", "resin bass bowed bite strong orchestral cello"],
  ["lead", "fizzy buzzy beefy aggressive hard synth"],
  ["vox", "fairlight nasal breathy piercing delicate thin vocal"],
  ["clav", "slap piano harpsichord distorted electric piano"],
  ["piano", "grand piano warm delicate aggressive rock dynamic"],
  ["piano", "real grand sweet acoustic piano classical"],
  ["flute", "flutey brass expressive muted modulation wind"],
  ["bass", "warm analog bass cinematic soft berlin"],
  ["organ", "synth flute organ chiff swell intriguing"],
  ["guitar", "guitar solo chordal pitch bend modulation"],
  ["guitar", "screaming guitar aggressive solo distorted lead"],
  ["strings", "soft warm analog strings emotive background pad"],
  ["choir", "deep massed vocal choir eerie mutated low"],
  ["lead", "warm fuzzy analog full solo synth"],
  ["strings", "deep dramatic strings impact foreground orchestral"],
  ["bass", "tight minimoog bass focused brittle metallic stab synth"],
  ["bell", "angel glass glossy transparent delicate atmospheric bell"],
];

const bytes = Uint8Array.from(atob(BANK), (c) => c.charCodeAt(0));

export const EMM_VOICES = META.map(([family, tags], i) => ({
  id: "emm-" + i,
  source: "EMM / Music Technology",
  family,
  tags: tags.split(" "),
  voice: unpackVoice([...bytes.slice(i * 128, i * 128 + 128)]),
}));
